(()=>{function r(){typeof gsap>"u"||document.querySelectorAll(".product-list--product").forEach(e=>{let t=e.querySelector(".product-list--img");t&&(e.addEventListener("mouseenter",()=>{gsap.to(t,{duration:.15,scale:.95,transformOrigin:"center center",ease:"power1.out"})}),e.addEventListener("mouseleave",()=>{gsap.to(t,{duration:.15,scale:1,transformOrigin:"center center",ease:"power1.out"})}))})}document.addEventListener("DOMContentLoaded",()=>{r()});})();
